ALTER TABLE salud_u.paciente ADD COLUMN id_principal uuid NULL UNIQUE REFERENCES salud_u.principal(id) ON DELETE RESTRICT;
CREATE TABLE salud_u.solicitud_cita (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),id_paciente uuid NOT NULL REFERENCES salud_u.paciente(id) ON DELETE RESTRICT,tipo_cita text NOT NULL,estado text NOT NULL DEFAULT 'PENDING',solicitado_en timestamptz NOT NULL DEFAULT now(),solicitado_por uuid NOT NULL REFERENCES salud_u.principal(id),cancelado_en timestamptz,motivo_cancelacion text,CONSTRAINT cita_solicitud_type CHECK(tipo_cita='INITIAL'),CONSTRAINT cita_solicitud_status CHECK(estado IN('PENDING','CANCELLED')));
CREATE UNIQUE INDEX cita_solicitud_one_pending_initial ON salud_u.solicitud_cita(id_paciente) WHERE estado='PENDING';
ALTER TABLE salud_u.solicitud_cita ENABLE ROW LEVEL SECURITY; ALTER TABLE salud_u.solicitud_cita FORCE ROW LEVEL SECURITY; CREATE POLICY cita_solicitud_migrator ON salud_u.solicitud_cita FOR ALL TO ${migrator_role} USING(true) WITH CHECK(true);
CREATE FUNCTION salud_u.crear_solicitud_inicial(p_paciente_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=salud_u,pg_temp AS $$ DECLARE actor uuid:=salud_u.id_actor_actual(); paciente uuid; solicitud_id uuid; BEGIN IF salud_u.tiene_rol_actor('STUDENT') THEN SELECT id INTO paciente FROM salud_u.paciente WHERE id_principal=actor AND archivado_en IS NULL; ELSIF salud_u.tiene_rol_actor('ADMINISTRATIVE') THEN paciente:=p_paciente_id; ELSE RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF; IF paciente IS NULL THEN RAISE EXCEPTION 'No existe un paciente asociado a la cuenta' USING ERRCODE='P0002'; END IF; INSERT INTO salud_u.solicitud_cita(id_paciente,tipo_cita,solicitado_por) VALUES(paciente,'INITIAL',actor) RETURNING id INTO solicitud_id; RETURN solicitud_id; END; $$;
CREATE FUNCTION salud_u.listar_mis_solicitudes_cita() RETURNS TABLE(id uuid,tipo_cita text,estado text,solicitado_en timestamptz,cancelado_en timestamptz,motivo_cancelacion text,id_paciente uuid,carnet text,nombre_paciente text) LANGUAGE sql SECURITY DEFINER SET search_path=salud_u,pg_temp AS $$ SELECT r.id,r.tipo_cita,r.estado,r.solicitado_en,r.cancelado_en,r.motivo_cancelacion,p.id,p.carnet,concat_ws(' ',p.nombres,p.apellidos) FROM salud_u.solicitud_cita r JOIN salud_u.paciente p ON p.id=r.id_paciente WHERE salud_u.tiene_rol_actor('ADMINISTRATIVE') OR (salud_u.tiene_rol_actor('STUDENT') AND p.id_principal=salud_u.id_actor_actual()) ORDER BY r.solicitado_en DESC $$;
CREATE FUNCTION salud_u.cancelar_solicitud_cita(p_id uuid,p_reason text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=salud_u,pg_temp AS $$ DECLARE row_data record; BEGIN SELECT r.*,p.id_principal INTO row_data FROM salud_u.solicitud_cita r JOIN salud_u.paciente p ON p.id=r.id_paciente WHERE r.id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Solicitud no encontrada' USING ERRCODE='P0002'; END IF; IF NOT(salud_u.tiene_rol_actor('ADMINISTRATIVE') OR (salud_u.tiene_rol_actor('STUDENT') AND row_data.id_principal=salud_u.id_actor_actual())) THEN RAISE EXCEPTION 'No autorizado' USING ERRCODE='42501'; END IF; IF row_data.estado<>'PENDING' THEN RAISE EXCEPTION 'La solicitud no puede cancelarse' USING ERRCODE='23514'; END IF; UPDATE salud_u.solicitud_cita SET estado='CANCELLED',cancelado_en=now(),motivo_cancelacion=nullif(btrim(p_reason),'') WHERE id=p_id; END; $$;
REVOKE ALL ON TABLE salud_u.solicitud_cita FROM PUBLIC; REVOKE ALL ON TABLE salud_u.solicitud_cita FROM ${runtime_role}; REVOKE ALL ON FUNCTION salud_u.crear_solicitud_inicial(uuid),salud_u.listar_mis_solicitudes_cita(),salud_u.cancelar_solicitud_cita(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION salud_u.crear_solicitud_inicial(uuid),salud_u.listar_mis_solicitudes_cita(),salud_u.cancelar_solicitud_cita(uuid,text) TO ${runtime_role};
